// How long a caller that asked to re-grade waits for the run to finish before
// reporting it as still in progress.
//
// Three surfaces implement this wait independently, because each one polls from
// where it stands: bitfab-web's MCP tool polls the run row in process, and the
// TypeScript and Python SDK clients poll GET .../rerunGraders over HTTP. They
// cannot share the loop, but they must not disagree on the policy, or the same
// re-run reports "still in progress" over MCP and "completed" from the SDK.
//
// This file is the source of truth. bitfab-web imports it, and
// `mcpContractParity.test.ts` pins both SDK copies to these numbers, so raising
// the wait in one language fails there until the others follow.
/** Total time a re-grade call waits for the run to reach a terminal status. */
export const GRADER_RERUN_TIMEOUT_MS = 90_000;
/** Gap between polls while waiting. */
export const GRADER_RERUN_POLL_INTERVAL_MS = 1_000;
